import { createRoute, z } from '@hono/zod-openapi'

const ServiceTCPSchema = z
  .object({
    protocol: z
      .enum(['tcp', 'http', 'https'])
      .openapi({ description: 'Protocol of the Load Balancer.' }),
    listen_port: z
      .int()
      .openapi({ description: 'Port the Load Balancer listens on.', example: 443 }),
    destination_port: z
      .int()
      .openapi({ description: 'Port the Load Balancer will balance to.', example: 80 }),
    proxyprotocol: z
      .boolean()
      .openapi({ description: 'Is Proxyprotocol enabled or not.', example: false }),
    health_check: z
      .strictObject({
        protocol: z
          .enum(['tcp', 'http'])
          .openapi({ description: 'Type of the health check.', example: 'http' }),
        port: z
          .int()
          .openapi({ description: 'Port the health check will be performed on.', example: 4711 }),
        interval: z
          .int()
          .min(3)
          .max(60)
          .openapi({
            description: 'Time interval in seconds health checks are performed.',
            example: 15,
          }),
        timeout: z
          .int()
          .min(1)
          .max(60)
          .openapi({
            description: 'Time in seconds after an attempt is considered a timeout.',
            example: 10,
          }),
        retries: z
          .int()
          .min(1)
          .max(5)
          .openapi({
            description:
              'Unsuccessful retries needed until a target is considered unhealthy; an unhealthy target needs the same number of successful retries to become healthy again.',
            example: 3,
          }),
        http: z
          .strictObject({
            domain: z
              .string()
              .max(128)
              .nullable()
              .openapi({
                description:
                  'Host header to send in the HTTP request. May not contain spaces, percent or backslash symbols. Can be null, in that case no host header is sent.',
                example: 'example.com',
              }),
            path: z
              .string()
              .min(1)
              .max(256)
              .openapi({
                description:
                  'HTTP path to use for health checks. May not contain literal spaces, use percent-encoding instead.',
                example: '/',
              }),
            response: z
              .string()
              .max(256)
              .exactOptional()
              .openapi({
                description:
                  'String that must be contained in HTTP response in order to pass the health check.',
                example: '{"status": "ok"}',
              }),
            status_codes: z
              .array(z.string())
              .max(20)
              .default(['2??', '3??'])
              .exactOptional()
              .openapi({
                description:
                  'List of returned HTTP status codes in order to pass the health check. Supports the wildcards `?` for exactly one character and `*` for multiple ones.',
                example: ['2??', '3??'],
              }),
            tls: z
              .boolean()
              .exactOptional()
              .openapi({ description: 'Use HTTPS for health check.', example: false }),
          })
          .exactOptional()
          .openapi({
            description: 'Additional configuration for protocol http.',
            required: ['domain', 'path'],
          }),
      })
      .openapi({
        title: 'LoadBalancerServiceHealthCheck',
        description: 'Service health check.',
        required: ['protocol', 'port', 'interval', 'timeout', 'retries'],
      }),
  })
  .openapi({
    required: ['protocol', 'listen_port', 'destination_port', 'proxyprotocol', 'health_check'],
  })
  .and(
    z
      .object({ protocol: z.literal('tcp').exactOptional().openapi({ example: 'tcp' }) })
      .openapi({ required: [] }),
  )
  .openapi({ title: 'LoadBalancerServiceTCP' })
  .openapi('ServiceTCP')

