const TargetTypeServerSchema = z
  .object({
    type: z
      .enum(['server', 'label_selector', 'ip'])
      .openapi({ description: 'Type of the resource.' }),
  })
  .openapi({ required: ['type'] })
  .and(
    z
      .object({
        type: z.literal('server').exactOptional().openapi({ example: 'server' }),
        server: z
          .object({
            id: z
              .preprocess(
                (val) =>
                  typeof val === 'number' && Number.isSafeInteger(val)
                    ? BigInt(val)
                    : typeof val === 'string' && /^-?\d+$/.test(val)
                      ? BigInt(val)
                      : val,
                z.int64(),
              )
              .openapi({
                type: 'integer',
                format: 'int64',
                description: 'ID of the Server.',
                example: 80,
              }),
            ip: z
              .string()
              .openapi({
                description:
                  "IP of the Server that the traffic is routed to. Either the Server's primary IPv4 or, if an IPv6 was specified when adding the target, an IPv6 within the Server's /64 subnet.",
                example: '2001:db8::1',
              }),
          })
          .openapi({
            title: 'LoadBalancerTargetServer',
            description:
              'Server where the traffic should be routed to. Only present for target type "server".',
            required: ['id', 'ip'],
          }),
        health_status: z
          .array(
            z
              .object({
                listen_port: z.int().openapi({ example: 443 }),
                status: z.enum(['healthy', 'unhealthy', 'unknown']).openapi({ example: 'healthy' }),
                detail: z
                  .enum([
                    'unspecified',
                    'layer4_no_connection',
                    'layer4_timeout',
                    'layer7_timeout',
                    'unexpected_http_status',
                    'unexpected_http_content',
                  ])
                  .exactOptional()
                  .openapi({
                    description:
                      'Additional details about why the health check failed. Only present when `status` is `unhealthy`.',
                    example: 'unexpected_http_status',
                  }),
                http_status_code: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      'HTTP status code returned by the target during the last health check. Only present when `status` is `unhealthy` and `detail` is `unexpected_http_status`.',
                    example: 503,
                  }),
              })
              .openapi({ required: ['listen_port', 'status'] }),
          )
          .openapi({
            title: 'LoadBalancerTargetHealthStatus',
            description:
              'List of health statuses of the services on this target. Only present for target types "server" and "ip".',
          }),
        use_private_ip: z
          .boolean()
          .default(false)
          .openapi({
            title: 'LoadBalancerTargetUsePrivateIP',
            description:
              'Use the private network IP instead of the public IP. Only present for target types "server" and "label_selector".',
          }),
      })
      .openapi({ required: ['server', 'health_status', 'use_private_ip'] }),
  )
  .openapi({ title: 'LoadBalancerTargetTypeServer' })
  .openapi('TargetTypeServer')

