const APITokenSecurityScheme = { type: 'http', scheme: 'bearer' }

export const getActionsRoute = createRoute({
  method: 'get',
  path: '/actions',
  tags: ['Actions'],
  summary: 'Get multiple Actions',
  description:
    'Returns multiple Action objects specified by the `id` parameter.\n\n**Note**: This endpoint previously allowed listing all actions in the project. This functionality was deprecated in July 2023 and removed on 30 January 2025.\n\n- Announcement: https://docs.hetzner.cloud/changelog#2023-07-20-actions-list-endpoint-is-deprecated\n- Removal: https://docs.hetzner.cloud/changelog#2025-01-30-listing-arbitrary-actions-in-the-actions-list-endpoint-is-removed\n',
  operationId: 'get_actions',
  request: {
    query: z.object({
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(
            z
              .preprocess((val) => {
                if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                  return val
                if (/^-?\d+$/.test(val)) return BigInt(val)
                const num = Number(val)
                return Number.isSafeInteger(num) ? BigInt(num) : val
              }, z.int64().min(1n).max(9007199254740991n))
              .openapi({
                type: 'integer',
                format: 'int64',
                minimum: 1,
                maximum: 9007199254740991,
                description: 'ID of the [Action](#description/actions).',
                example: 42,
              }),
          ),
        )
        .openapi({
          param: {
            description:
              'Filter the actions by ID. May be used multiple times.\n\nThe response will only contain actions matching the specified IDs.\n',
            name: 'id',
            in: 'query',
            required: true,
            schema: {
              type: 'array',
              items: {
                description: 'ID of the [Action](#description/actions).',
                type: 'integer',
                format: 'int64',
                minimum: 1,
                maximum: 9007199254740991,
                example: 42,
              },
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Request succeeded.',
      content: {
        'application/json': {
          schema: z
            .object({
              actions: z.array(
                z
                  .object({
                    id: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64().min(1n).max(9007199254740991n),
                      )
                      .openapi({
                        type: 'integer',
                        format: 'int64',
                        minimum: 1,
                        maximum: 9007199254740991,
                        description: 'ID of the [Action](#description/actions).',
                        example: 42,
                      }),
                    command: z
                      .string()
                      .openapi({
                        description: 'Command executed in the Action.',
                        example: 'start_resource',
                      }),
                    status: z
                      .enum(['running', 'success', 'error'])
                      .openapi({ description: 'Status of the Action.' }),
                    started: z.iso
                      .datetime({ offset: true })
                      .openapi({
                        description:
                          'Point in time when the Action was started (in [RFC3339](https://datatracker.ietf.org/doc/html/rfc3339#section-5.6) format).',
                        example: '2016-01-30T23:55:00Z',
                      }),
                    finished: z.iso
                      .datetime({ offset: true })
                      .nullable()
                      .openapi({
                        description:
                          'Point in time when the Action was finished (in [RFC3339](https://datatracker.ietf.org/doc/html/rfc3339#section-5.6) format). Only set if the Action is finished otherwise null.',
                        example: '2016-01-30T23:55:00Z',
                      }),
                    progress: z
                      .int32()
                      .openapi({ description: 'Progress of the Action in percent.', example: 100 }),
                    resources: z
                      .array(
                        z
                          .object({
                            id: z
                              .preprocess(
                                (val) =>
                                  typeof val === 'number' && Number.isSafeInteger(val)
                                    ? BigInt(val)
                                    : typeof val === 'string' && /^-?\d+$/.test(val)
                                      ? BigInt(val)
                                      : val,
                                z.int64().min(1n).max(9007199254740991n),
                              )
                              .openapi({
                                type: 'integer',
                                format: 'int64',
                                minimum: 1,
                                maximum: 9007199254740991,
                                description: 'ID of the Resource.',
                                example: 42,
                              }),
                            type: z
                              .string()
                              .openapi({ description: 'Type of the Resource.', example: 'server' }),
                          })
                          .openapi({ required: ['id', 'type'] }),
                      )
                      .openapi({ description: 'Resources the Action relates to.' }),
                    error: z
                      .object({
                        code: z
                          .string()
                          .openapi({
                            description: 'Fixed error code for machines.',
                            example: 'action_failed',
                          }),
                        message: z
                          .string()
                          .openapi({
                            description: 'Error message for humans.',
                            example: 'Action failed',
                          }),
                      })
                      .nullable()
                      .openapi({
                        description:
                          'Error message for the Action if an error occurred, otherwise null.',
                        required: ['code', 'message'],
                      }),
                  })
                  .openapi({
                    title: 'Action',
                    required: [
                      'id',
                      'command',
                      'status',
                      'progress',
                      'started',
                      'finished',
                      'resources',
                      'error',
                    ],
                  }),
              ),
            })
            .openapi({ title: 'ActionListResponse', required: ['actions'] }),
        },
      },
    },
    '4xx': {
      description: 'Request failed with a user error.',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({
                  code: z.string().openapi({ description: 'Error code for machines.' }),
                  message: z.string().openapi({ description: 'Error message for humans.' }),
                  details: z
                    .object({})
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Details about the error.' }),
                })
                .openapi({ required: ['code', 'message'] }),
            })
            .openapi({
              required: ['error'],
              example: {
                error: { code: 'unauthorized', message: 'unable to authenticate', details: null },
              },
            }),
        },
      },
    },
    '5xx': {
      description: 'Request failed with a server error.',
      content: {
        'application/json': {
          schema: z
            .object({
              error: z
                .object({
                  code: z.string().openapi({ description: 'Error code for machines.' }),
                  message: z.string().openapi({ description: 'Error message for humans.' }),
                  details: z
                    .object({})
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Details about the error.' }),
                })
                .openapi({ required: ['code', 'message'] }),
            })
            .openapi({
              required: ['error'],
              example: { error: { code: 'timeout', message: 'request timeout', details: null } },
            }),
        },
      },
    },
  },
  security: [{ APIToken: [] }],
})

